from datetime import datetime
from typing import Any

from pydantic import BaseModel, ConfigDict, EmailStr, Field, field_serializer, field_validator

DISCLAIMER = (
    "Educational demonstration only. This result is generated by a machine-learning model trained on a small "
    "public dataset. It is NOT a medical diagnosis, may be inaccurate, and does not replace a qualified "
    "healthcare professional. If you have chest pain, shortness of breath, fainting or any emergency symptoms, "
    "seek urgent medical care immediately."
)


class _UTCModel(BaseModel):
    @field_serializer("created_at", check_fields=False)
    def _ser_dt(self, v: datetime) -> str:
        return v.isoformat() + "Z" if v.tzinfo is None else v.isoformat()


class RegisterRequest(BaseModel):
    name: str = Field(min_length=1, max_length=100)
    email: EmailStr
    password: str = Field(min_length=8)

    @field_validator("name")
    @classmethod
    def _strip(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("Name must not be blank")
        return v

    @field_validator("password")
    @classmethod
    def _bcrypt_limit(cls, v: str) -> str:
        if len(v.encode("utf-8")) > 72:
            raise ValueError("Password must be at most 72 bytes")
        return v


class LoginRequest(BaseModel):
    email: EmailStr
    password: str = Field(min_length=1, max_length=200)


class UserOut(_UTCModel):
    model_config = ConfigDict(from_attributes=True)
    id: int
    name: str
    email: EmailStr
    created_at: datetime


class TokenResponse(BaseModel):
    access_token: str
    token_type: str = "bearer"
    user: UserOut


class PredictRequest(BaseModel):
    inputs: dict[str, Any]


class PredictionOut(_UTCModel):
    id: int
    predicted_class: int
    predicted_label: str
    model_score: float | None
    model_version: str
    inputs: dict[str, Any]
    warnings: list[str]
    created_at: datetime
    disclaimer: str = DISCLAIMER


class HistoryOut(BaseModel):
    items: list[PredictionOut]
    total: int
    skip: int
    limit: int
